import{_ as t,o as i,c as l,a2 as o}from"./chunks/framework.DpXDHk3d.js";const u=JSON.parse('{"title":"5.5 热继电器","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/05-chapter-5-chang-yong-di-ya-dian-qi/5-5-re-ji-dian-qi.md","filePath":"electrician/low-voltage-electrician/05-chapter-5-chang-yong-di-ya-dian-qi/5-5-re-ji-dian-qi.md","lastUpdated":1793095197000}'),r={name:"electrician/low-voltage-electrician/05-chapter-5-chang-yong-di-ya-dian-qi/5-5-re-ji-dian-qi.md"};function e(n,a,s,g,h,c){return i(),l("div",null,[...a[0]||(a[0]=[o('<h1 id="_5-5-热继电器" tabindex="-1">5.5 热继电器 <a class="header-anchor" href="#_5-5-热继电器" aria-label="Permalink to &quot;5.5 热继电器&quot;">​</a></h1><h2 id="本节导读" tabindex="-1">本节导读 <a class="header-anchor" href="#本节导读" aria-label="Permalink to &quot;本节导读&quot;">​</a></h2><p>热继电器是电动机的&quot;护身符&quot;——专门管<strong>过载保护</strong>。电动机过载时电流变大、发热严重,热继电器靠&quot;热&quot;来感知并切断电源。这一节讲原理、整定电流和注意事项。</p><h2 id="一、作用-电动机的过载保护" tabindex="-1">一、作用:电动机的过载保护 <a class="header-anchor" href="#一、作用-电动机的过载保护" aria-label="Permalink to &quot;一、作用:电动机的过载保护&quot;">​</a></h2><p>电动机正常运行时电流是额定电流;但负载过重、堵转、电压异常时,电流长时间偏大,线圈发热严重,会烧坏电动机。<strong>热继电器</strong>就是检测这种&quot;长时间过电流(过载)&quot;并切断电源的保护电器。</p><ul><li>保护对象:<strong>电动机过载</strong>;</li><li>注意:热继电器<strong>不能作短路保护</strong>(短路电流太大、动作太慢),短路保护靠熔断器/断路器。</li></ul><h2 id="二、工作原理-双金属片" tabindex="-1">二、工作原理:双金属片 <a class="header-anchor" href="#二、工作原理-双金属片" aria-label="Permalink to &quot;二、工作原理:双金属片&quot;">​</a></h2><p>热继电器的核心是<strong>双金属片</strong>:</p><ul><li>双金属片由两种热膨胀系数不同的金属复合而成;</li><li>电流通过热元件(加热电阻)给双金属片加热;</li><li><strong>过载时电流大 → 双金属片受热弯曲 → 推动动作机构 → 常闭触头断开 → 切断接触器线圈电源 → 电动机停转</strong>;</li><li>温度降下来后,双金属片恢复原状,可<strong>复位</strong>。</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>过载电流 ──► 加热双金属片 ──► 弯曲 ──► 常闭触头断开 ──► 接触器断电 ──► 电动机停转</span></span></code></pre></div><blockquote><p>💡 为什么叫&quot;热&quot;继电器?因为它靠<strong>发热、靠热惯性</strong>动作,和电流的发热效应直接挂钩。电流越大、时间越长,越容易动作——正好符合过载的特点。</p></blockquote><h2 id="三、热继电器的结构" tabindex="-1">三、热继电器的结构 <a class="header-anchor" href="#三、热继电器的结构" aria-label="Permalink to &quot;三、热继电器的结构&quot;">​</a></h2><ul><li><strong>热元件</strong>(双金属片 + 加热电阻):感知过载;</li><li><strong>触头系统</strong>:一般有一对常闭触头,串在接触器控制回路里;</li><li><strong>电流整定装置</strong>:调整整定电流;</li><li><strong>复位机构</strong>:自动复位或手动复位。</li></ul><h2 id="四、电流整定-重要" tabindex="-1">四、电流整定(重要) <a class="header-anchor" href="#四、电流整定-重要" aria-label="Permalink to &quot;四、电流整定(重要)&quot;">​</a></h2><ul><li><strong>整定电流</strong>:热继电器动作的电流基准,可调节;</li><li>选用原则:<strong>整定电流应等于或略小于电动机的额定电流</strong>(一般取额定电流的 1~1.05 倍左右,按实际可微调);</li><li>若整定电流太大,过载时不动作,失去保护作用;太小,正常运行时误动作。</li></ul><blockquote><p>⚠️ 高频考点:热继电器的<strong>整定电流要等于(或略小于)电动机额定电流</strong>。</p></blockquote><h2 id="五、为什么电动机过载不用熔断器" tabindex="-1">五、为什么电动机过载不用熔断器 <a class="header-anchor" href="#五、为什么电动机过载不用熔断器" aria-label="Permalink to &quot;五、为什么电动机过载不用熔断器&quot;">​</a></h2><p>电动机启动电流可达额定电流的 <strong>4~7 倍</strong>,若用熔断器保护,启动瞬间就烧断了。热继电器有&quot;热惯性&quot;(加热需要时间),既能躲过启动电流,又能在长时间过载时动作——所以电动机用<strong>热继电器做过载保护</strong>。</p><h2 id="六、考点提示" tabindex="-1">六、考点提示 <a class="header-anchor" href="#六、考点提示" aria-label="Permalink to &quot;六、考点提示&quot;">​</a></h2><ul><li>✅ 热继电器 = <strong>电动机过载保护</strong>,靠双金属片受热弯曲动作。</li><li>✅ 整定电流 ≈ 电动机<strong>额定电流</strong>。</li><li>✅ 热继电器<strong>不能做短路保护</strong>。</li><li>⚠️ 易混点:过载保护(热继电器)与短路保护(熔断器/断路器)分工不同。</li></ul><h2 id="七、本节小结" tabindex="-1">七、本节小结 <a class="header-anchor" href="#七、本节小结" aria-label="Permalink to &quot;七、本节小结&quot;">​</a></h2><ul><li>热继电器靠双金属片感知过载,切断接触器控制回路。</li><li>整定电流等于(略小于)电动机额定电流。</li><li>热惯性使其能躲过启动电流,专门管过载。</li></ul><h2 id="八、自测练习" tabindex="-1">八、自测练习 <a class="header-anchor" href="#八、自测练习" aria-label="Permalink to &quot;八、自测练习&quot;">​</a></h2><ol><li>(判断)热继电器是电动机的过载保护电器。( )</li><li>(判断)热继电器可用于短路保护。( )</li><li>(单选)热继电器的整定电流一般应()电动机额定电流。 A. 大于　B. 等于或略小于　C. 远大于　D. 无关</li><li>(单选)热继电器的核心动作元件是()。 A. 电磁铁　B. 双金属片　C. 弹簧　D. 熔体</li><li>(判断)热继电器动作后,等温度下降,可以手动或自动复位。( )</li></ol><details><summary>参考答案(点击展开)</summary><ol><li><strong>√</strong>。热继电器管电动机过载保护。</li><li><strong>×</strong>。热继电器不能做短路保护,短路保护用熔断器/断路器。</li><li><strong>B</strong>。整定电流等于或略小于额定电流。</li><li><strong>B</strong>。双金属片受热弯曲是动作核心。</li><li><strong>√</strong>。冷却后可手动或自动复位。</li></ol></details>',25)])])}const p=t(r,[["render",e]]);export{u as __pageData,p as default};
